effect.shader:
precision highp float;

void main() {
    // Normalized coordinates (0.0 to 1.0)
    vec2 uv = acScreenNorm;

    // Adjust for aspect ratio to make circle/distortions uniform
    float aspect = acScreenSize.x / acScreenSize.y;
    vec2 aspectUV = uv * vec2(aspect, 1.0);

    // Convert Alight Motion point params (0-1000) to 0-1 range
    // Then apply aspect ratio correction
    vec2 center = (startPoint / 1000.0) * vec2(aspect, 1.0);
    vec2 end = (endPoint / 1000.0) * vec2(aspect, 1.0);

    float stretchStrength = strength * 3.0; // Scaled to match Shadertoys multiplier
    vec2 dirVec = end - center;
    vec2 dir = normalize(dirVec);

    // 1. Calculate how far along the stretch axis the pixel is
    float projection = dot(aspectUV - center, dir);

    // 2. Calculate the distance from center for the Radius mask
    float dist = length(aspectUV - center);

    // 3. Create the Radius Falloff (normalized radius)
    // Shadertoy used a raw float, here we use radius param
    // smoothstep(radius, 0.0, dist) means:
    // dist >= radius -> 0.0
    // dist <= 0.0 -> 1.0
    float mask = smoothstep(radius, 0.0, dist);

    vec2 distortedUV = uv;

    if (projection > 0.0) {
        // Apply the stretch, but multiply the intensity by the mask
        float amount = (stretchStrength / (1.0 + stretchStrength)) * mask;
        // Move aspect-corrected uv back towards center
        vec2 deltaDistort = dir * projection * amount;
        // Scale delta back to non-aspect space for final UV
        deltaDistort.x /= aspect;
        distortedUV -= deltaDistort;
    }

    // Sample inputImg
    vec4 col = texture2DCv(inputImg.texture, distortedUV);

    // Edge clamping / Keep Edge logic
    if (!keepEdge) {
        if (distortedUV.x > 1.0 || distortedUV.x < 0.0 || distortedUV.y > 1.0 || distortedUV.y < 0.0) {
            col = vec4(0.0);
        }
    } else {
        col = texture2DCv(inputImg.texture, clamp(distortedUV, 0.0, 1.0));
    }

    gl_FragColor = col;
}
